from collections import Counter
def remove_duplicate(s):
    # Using Counter to count occurrences of each word
    word_count = Counter(s.split())
    # Filtering out words with a count of 1
    unique_words = {word: count for word, count in word_count.items() if count > 0}
    # Joining the words to form the final string
    return ' '.join(unique_words.keys())

