import math

# Function to count the number of distinct power of prime factor of a given number
def count_Fac(num):
    # Initialize a set to store unique prime factors
    unique_factors = set()

    # Loop through all numbers from 2 to the square root of the number
    for i in range(3, int(math.sqrt(num)) + 1):
        # Check if i is a factor of the number
        if num % i == 0:
            # Add i to the set of unique factors
            unique_factors.add(i)
            # Divide the number by i until it is no longer divisible
            while num % i == 0:
                num //= i

    # If num is still greater than 1, it means it is a prime number greater than 1
    if num > 1:
        unique_factors.add(num)

    # The number of distinct prime factors is the size of the set
    return len(unique_factors)

