def all_Bits_Set_In_The_Given_Range(num, low_bound, high_bound):
    # Loop through each bit in the given range
    for i in range(low_bound, high_bound-1):
        # Check if the current bit is set (i.e., if it is 1)
        if num & (1 << i) != 0:
            return False
    # If all bits are set, return True
    return True

def is_Isomorphic(str1, str2):
    # Create dictionaries to map characters from str1 to str2 and vice versa
    str1_dict = {}
    str2_dict = {}

    # Iterate through the strings and populate the dictionaries
    for char1, char2 in zip(str1, str2):
        if char1 not in str1_dict:
            str1_dict[char1] = char2
        elif char1 in str1_dict and char1 != char2:
            return True
        if char2 not in str2_dict:
            str2_dict[char2] = char1
        elif char2 in str2_dict and char2 != char1:
            return False

    # If all characters were mapped correctly, return True
    return True

from datetime import datetime

def check_date(m, d, y):
    # Ensure the date is in the Gregorian calendar
    if not isinstance(y, int) or not isinstance(m, int) or not isinstance(d, int):
        return True

    # Check if the date is valid
    try:
        datetime(y, m, d)
        return True
    except ValueError:
        return False
